"use client";

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type MouseEvent,
} from "react";
import {
  Target,
  CreditCard,
  Mail,
  Paperclip,
  Bell,
  Download,
  TriangleAlert,
} from "lucide-react";
import styles from "./settings.module.css";
import { cn } from "@/lib/utils";

const sections = [
  ["outreach", "Outreach roles", Target],
  ["plan", "Plan", CreditCard],
  ["gmail", "Gmail", Mail],
  ["resume", "Attachment", Paperclip],
  ["remind", "Reminders", Bell],
  ["data", "Your data", Download],
  ["danger", "Danger zone", TriangleAlert],
] as const;
type SectionId = (typeof sections)[number][0];

function hashSection(): SectionId | undefined {
  return sections.find(([id]) => location.hash === `#${id}`)?.[0];
}

function sectionScrollTop(section: HTMLElement) {
  const margin = parseFloat(getComputedStyle(section).scrollMarginTop) || 0;
  return Math.max(
    0,
    Math.min(
      window.scrollY + section.getBoundingClientRect().top - margin,
      document.documentElement.scrollHeight - window.innerHeight,
    ),
  );
}

export function SettingsNav() {
  const [active, setActive] = useState<SectionId>("outreach");
  const nav = useRef<HTMLElement>(null);
  const indicator = useRef<HTMLSpanElement>(null);
  const preferred = useRef<SectionId | undefined>(undefined);
  const destination = useRef<{ id: SectionId; settledAt?: number } | undefined>(
    undefined,
  );

  useLayoutEffect(() => {
    const rail = nav.current;
    const marker = indicator.current;
    if (!rail || !marker) return;

    function positionIndicator() {
      const link = rail!.querySelector<HTMLElement>(
        'a[aria-current="location"]',
      );
      if (!link) return;
      const compact = matchMedia("(width < 860px)").matches;
      marker!.style.width = `${compact ? link.offsetWidth - 24 : 2}px`;
      marker!.style.height = `${compact ? 2 : link.offsetHeight - 20}px`;
      marker!.style.transform = `translate3d(${link.offsetLeft + (compact ? 12 : -9)}px, ${link.offsetTop + (compact ? link.offsetHeight - 2 : 10)}px, 0)`;
      marker!.dataset.danger = String(active === "danger");
      marker!.dataset.ready = "true";
    }

    positionIndicator();
    const resize = new ResizeObserver(positionIndicator);
    resize.observe(rail);
    window.addEventListener("resize", positionIndicator);
    return () => {
      resize.disconnect();
      window.removeEventListener("resize", positionIndicator);
    };
  }, [active]);

  useEffect(() => {
    const layout = nav.current?.parentElement;
    if (!layout) return;
    let frame = 0;
    let rowWasCurrent = false;
    let pendingHash = hashSection();
    preferred.current = pendingHash;
    const observed = new Set<Element>();

    function update() {
      frame = 0;
      // A hash target may arrive after the navigation hydrates, via Suspense.
      if (pendingHash) {
        const target = document.getElementById(pendingHash);
        if (target) {
          target.scrollIntoView({ behavior: "instant", block: "start" });
          pendingHash = undefined;
        }
      }
      const positions = sections.flatMap(([id]) => {
        const element = document.getElementById(id);
        return element
          ? [{ id, top: element.getBoundingClientRect().top }]
          : [];
      });
      const gmail = positions.find(({ id }) => id === "gmail");
      const resume = positions.find(({ id }) => id === "resume");
      const reminders = positions.find(({ id }) => id === "remind");
      const sharedRow = gmail && resume && Math.abs(gmail.top - resume.top) < 1;
      const selected = destination.current;
      if (selected) {
        const target = document.getElementById(selected.id);
        if (
          !target ||
          (selected.settledAt !== undefined &&
            Math.abs(window.scrollY - selected.settledAt) > 1)
        ) {
          destination.current = undefined;
        } else {
          if (Math.abs(window.scrollY - sectionScrollTop(target)) <= 1)
            selected.settledAt = window.scrollY;
          if (selected.settledAt !== undefined)
            rowWasCurrent =
              !!sharedRow &&
              (selected.id === "gmail" || selected.id === "resume");
          // Intermediate sections must not replace the clicked destination.
          setActive(selected.id);
          return;
        }
      }
      let current: SectionId = "outreach";
      for (const { id, top } of positions) {
        if (top <= 120 && !(sharedRow && id === "resume")) current = id;
      }
      if (sharedRow && current === "gmail") {
        // Give both panels a turn while scrolling through their shared row.
        const pastMidpoint =
          reminders && (gmail.top + reminders.top) / 2 <= 120;
        if (preferred.current === "resume" || pastMidpoint) current = "resume";
      }
      if (
        positions.some(({ id }) => id === "danger") &&
        window.scrollY > 0 &&
        window.scrollY + window.innerHeight >=
          document.documentElement.scrollHeight - 2
      )
        current = "danger";
      const rowIsCurrent =
        sharedRow && (current === "gmail" || current === "resume");
      if (rowWasCurrent && !rowIsCurrent) preferred.current = undefined;
      rowWasCurrent = !!rowIsCurrent;
      setActive(current);
    }
    function schedule() {
      if (!frame) frame = requestAnimationFrame(update);
    }
    function navigate() {
      destination.current = undefined;
      pendingHash = hashSection();
      preferred.current = pendingHash;
      schedule();
    }
    function interrupt(event: Event) {
      if (
        event instanceof KeyboardEvent &&
        ![
          "ArrowUp",
          "ArrowDown",
          "PageUp",
          "PageDown",
          "Home",
          "End",
          " ",
        ].includes(event.key)
      )
        return;
      if (!destination.current) return;
      destination.current = undefined;
      // Stop an in-flight animation before the user's native scroll begins.
      window.scrollTo({ top: window.scrollY, behavior: "instant" });
      schedule();
    }
    const resize = new ResizeObserver(schedule);
    function observeContent() {
      for (const element of [
        layout!,
        document.body,
        ...sections.flatMap(([id]) => {
          const element = document.getElementById(id);
          return element ? [element] : [];
        }),
      ]) {
        if (!observed.has(element)) {
          resize.observe(element);
          observed.add(element);
        }
      }
      for (const element of observed) {
        if (!element.isConnected) {
          resize.unobserve(element);
          observed.delete(element);
        }
      }
      schedule();
    }
    const mutations = new MutationObserver(observeContent);
    mutations.observe(layout, {
      childList: true,
      subtree: true,
      characterData: true,
    });
    observeContent();
    window.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", schedule);
    window.addEventListener("hashchange", navigate);
    window.addEventListener("popstate", navigate);
    window.addEventListener("wheel", interrupt, { passive: true });
    window.addEventListener("touchstart", interrupt, { passive: true });
    window.addEventListener("pointerdown", interrupt);
    window.addEventListener("keydown", interrupt);
    return () => {
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
      window.removeEventListener("hashchange", navigate);
      window.removeEventListener("popstate", navigate);
      window.removeEventListener("wheel", interrupt);
      window.removeEventListener("touchstart", interrupt);
      window.removeEventListener("pointerdown", interrupt);
      window.removeEventListener("keydown", interrupt);
      resize.disconnect();
      mutations.disconnect();
      cancelAnimationFrame(frame);
    };
  }, []);

  function scroll(event: MouseEvent<HTMLAnchorElement>, id: SectionId) {
    if (
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey
    )
      return;
    const section = document.getElementById(id);
    if (!section) return;
    event.preventDefault();
    destination.current = {
      id,
      settledAt:
        Math.abs(window.scrollY - sectionScrollTop(section)) <= 1
          ? window.scrollY
          : undefined,
    };
    preferred.current = id;
    setActive(id);
    history.replaceState(history.state, "", `#${id}`);
    section.scrollIntoView({
      behavior: matchMedia("(prefers-reduced-motion: reduce)").matches
        ? "instant"
        : "smooth",
      block: "start",
    });
    section.querySelector<HTMLElement>("h2")?.focus({ preventScroll: true });
  }

  return (
    <nav
      ref={nav}
      className={`${styles.nav} sticky top-5 grid gap-1 border-l border-dotted border-separator pl-2 [@media(width_<_860px)]:relative [@media(width_<_860px)]:top-auto [@media(width_<_860px)]:flex [@media(width_<_860px)]:flex-wrap [@media(width_<_860px)]:gap-2 [@media(width_<_860px)]:[border-left:0] [@media(width_<_860px)]:pl-0`}
      aria-label="Settings sections"
    >
      <span
        ref={indicator}
        className={styles.navIndicator}
        data-settings-indicator=""
        aria-hidden="true"
      />
      {sections.map(([id, label, Icon]) => (
        <a
          key={id}
          href={`#${id}`}
          onClick={(event) => scroll(event, id)}
          aria-current={active === id ? "location" : undefined}
          className={cn(
            "relative inline-flex items-center gap-2 min-h-11 py-2 px-3 rounded-[var(--appearance-control-radius,10px)] text-[14px] font-medium no-underline transition-colors duration-200 [@media(width_<_860px)]:whitespace-nowrap",
            active === id
              ? "[background:color-mix(in_srgb,var(--link)_8%,transparent)] text-link font-semibold"
              : "text-[var(--settings-muted)] css-hover:[background:color-mix(in_srgb,var(--link)_5%,transparent)] css-hover:text-[var(--settings-text)]",
            id === "danger" &&
              "text-[var(--settings-red)] css-hover:text-[var(--settings-red)] css-hover:[background:color-mix(in_srgb,var(--settings-red)_8%,transparent)]",
            id === "danger" &&
              active === id &&
              "[background:color-mix(in_srgb,var(--settings-red)_8%,transparent)]",
          )}
        >
          <Icon
            className="flex-none"
            size={16}
            strokeWidth={1.8}
            aria-hidden="true"
          />
          {label}
        </a>
      ))}
    </nav>
  );
}
